  let neg = false;
  if (s[0] === '+' || s[0] === '-') { neg = s[0] === '-'; s = s.slice(1); }
  let dot = s.indexOf('.');
  let intPart, frac;
  if (dot === -1) { intPart = s; frac = ''; } else { intPart = s.slice(0, dot); frac = s.slice(dot + 1); }
  if (intPart === '') intPart = '0';
  // pad fraction to at least 3 digits
  while (frac.length < 3) frac += '0';
  let keep = frac.slice(0, 2); // two digits to keep
  let rest = frac.slice(2);
  let roundUp = false;
  // compare rest to "5000..."
  let first = rest[0];
  if (first > '5') roundUp = true;
  else if (first === '5') {
    let nonzero = false;
    for (let i = 1; i < rest.length; i++) if (rest[i] !== '0') { nonzero = true; break; }
    if (nonzero) roundUp = true;
    else {
      // exact tie: round to even
      let lastKeep = keep.charCodeAt(keep.length - 1) - 48;
      if (lastKeep % 2 === 1) roundUp = true;
    }
  }
  let digits = intPart + keep;
  let n = BigInt(digits);
  if (roundUp) n += 1n;
  let str = n.toString();
  while (str.length < 3) str = '0' + str;
  let out = str.slice(0, str.length - 2) + '.' + str.slice(str.length - 2);
  if (out === '0.00' || out === '-0.00') return '0.00';
  return (neg ? '-' : '') + out;
}

